class Solution {
public:
    long long numberOfWeeks(vector<int>& milestones) {
        priority_queue<int> pq(milestones.begin(), milestones.end());
        int prev = pq.top(); pq.pop();
        --prev;
        long long weeks = 1;
        while (!pq.empty()) {
            int top = pq.top(); pq.pop();
            ++weeks;
            if (prev > 0) pq.push(prev);
            prev = top - 1;
        }
        return weeks;
    }
};

