class Solution {
    public long numberOfWeeks(int[] milestones) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int x : milestones) pq.offer(x);
        int prev = pq.poll() - 1;
        long weeks = 1;
        while (!pq.isEmpty()) {
            int top = pq.poll();
            ++weeks;
            if (prev > 0) pq.offer(prev);
            prev = top - 1;
        }
        return weeks;
    }
}

