var numberOfWeeks = function(milestones) {
    const h = [...milestones];
    const siftDown = (i) => {
        const n = h.length;
        while (true) {
            let l = 2 * i + 1, r = l + 1, m = i;
            if (l < n && h[l] > h[m]) m = l;
            if (r < n && h[r] > h[m]) m = r;
            if (m === i) break;
            [h[i], h[m]] = [h[m], h[i]];
            i = m;
        }
    };
    for (let i = (h.length >> 1) - 1; i >= 0; i--) siftDown(i);
    const pop = () => {
        const top = h[0];
        const last = h.pop();
        if (h.length) {
            h[0] = last;
            siftDown(0);
        }
        return top;
    };
    const push = (x) => {
        h.push(x);
        let i = h.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (h[p] >= h[i]) break;
            [h[i], h[p]] = [h[p], h[i]];
            i = p;
        }
    };
    let prev = pop() - 1;
    let weeks = 1;
    while (h.length) {
        const top = pop();
        weeks++;
        if (prev > 0) push(prev);
        prev = top - 1;
    }
    return weeks;
};

