class Solution {
public:
    long long numberOfWeeks(vector<int>& milestones) {
        long long s = accumulate(milestones.begin(), milestones.end(), 0LL);
        long long m = *max_element(milestones.begin(), milestones.end());
        long long rest = s - m;
        return m <= rest + 1 ? s : 2 * rest + 1;
    }
};

