class Solution {
    public long numberOfWeeks(int[] milestones) {
        long s = 0, m = 0;
        for (int x : milestones) {
            s += x;
            m = Math.max(m, x);
        }
        long rest = s - m;
        return m <= rest + 1 ? s : 2 * rest + 1;
    }
}

